upstream api {
  least_conn;
  server 10.0.1.11:8080 max_fails=3 fail_timeout=10s;
  server 10.0.1.12:8080 max_fails=3 fail_timeout=10s;
  keepalive 256;
}
server {
  listen 443 ssl http2;
  ssl_certificate /etc/edge/cert.pem;
  ssl_certificate_key /etc/edge/key.pem;
  # Strip spoofable headers, then set canonical ones.
  proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
  proxy_set_header X-Forwarded-Proto $scheme;
  proxy_set_header Host $host;
  # One timeout budget: edge longer than backend p99, retries only for GET.
  proxy_connect_timeout 2s;
  proxy_read_timeout 5s;
  proxy_next_upstream error timeout http_502;
  proxy_next_upstream_tries 2;
  location /static/ {
    proxy_cache static_zone;
    proxy_cache_valid 200 10m;
    proxy_cache_key "$request_method|$host|$request_uri";
    proxy_pass http://api;
  }
  location /api/ {
    proxy_pass http://api;
    proxy_http_version 1.1;
    proxy_set_header Connection "";
  }
}
